\[
f(v)\le f(u)+\langle\nabla f(u),v-u\rangle+\frac{L}{2}\|v-u\|^{2}.
\tag{L1}
\]
\end{lemma}
\begin{proof}
Standard consequence of the integral form of the gradient Lipschitz condition. \qedhere
\end{proof}

\begin{lemma}[Gradient bound for $L$‑smooth functions]\label{lem:grad-bound}
For an $L$‑smooth function $f$ and any $z\in\R^{d}$,
\[
\frac{1}{2L}\,\|\nabla f(z)\|^{2}\;\le\;f(z)-f^\star .
\tag{L2}
\]
\end{lemma}
\begin{proof}
From Lemma~\ref{lem:smooth} with $u=z$, $v=z-\frac{1}{L}\nabla f(z)$ we obtain
\[
f\!\Bigl(z-\frac{1}{L}\nabla f(z)\Bigr)
\le f(z)-\frac{1}{L}\|\nabla f(z)\|^{2}
+\frac{L}{2}\Bigl\|\frac{1}{L}\nabla f(z)\Bigr\|^{2}
= f(z)-\frac{1}{2L}\|\nabla f(z)\|^{2}.
\]
Since $f^\star\le f\!\bigl(z-\frac{1}{L}\nabla f(z)\bigr)$, rearranging yields the claim. \qedhere
\end{proof}

