\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem~\ref{thm:main}.  Throughout the proof we denote
\[
\Delta_k:=f(x_k)-f^\star\ge0.
\]

\noindent\textbf{Step 0 (Momentum range).}  
By the modified definition \eqref{eq:beta} we have $0\le\beta_k<1$ for every $k\ge0$; in particular $\beta_0=0$ eliminates the negative value that appeared in the original manuscript.

\noindent\textbf{Step 1 (Potential function).}  
Define the Lyapunov sequence  

\[
\Phi_k:=\Delta_k+\frac{1-\beta_k}{2\alpha}\|x_k-x_{k-1}\|^{2},
\qquad k\ge0,
\tag{P1}
\]
with the convention $x_{-1}=x_0$ so that the kinetic term vanishes for $k=0$.

\noindent\textbf{Step 2 (Relation between successive potentials).}  
From the definition of $y_k$,
\[
y_k-x_k=\beta_k (x_k-x_{k-1}),
\qquad\text{hence}\qquad
x_k-y_k=-\beta_k (x_k-x_{k-1}). \tag{P2}
\]

\noindent\textbf{Step 3 (Expand $\|x_{k+1}-x_k\|^{2}$).}  
Using the update rule $x_{k+1}=y_k-\alpha\nabla f(y_k)$,
\[
\begin{aligned}
x_{k+1}-x_k
&= (y_k-x_k)-\alpha\nabla f(y_k)\\
&= \beta_k (x_k-x_{k-1})-\alpha\nabla f(y_k). \tag{P3}
\end{aligned}
\]

\noindent\textbf{Step 4 (Bound the kinetic term).}  
Square \eqref{P3} and use $2\langle a,b\rangle\le\|a\|^{2}+\|b\|^{2}$:
\[
\begin{aligned}
\|x_{k+1}-x_k\|^{2}
&\le 2\beta_k^{2}\|x_k-x_{k-1}\|^{2}
   +2\alpha^{2}\|\nabla f(y_k)\|^{2}. \tag{P4}
\end{aligned}
\]

\noindent\textbf{Step 5 (Descent of the function values).}  
Lemma~\ref{lem:descent} gives
\[
\Delta_{k+1}=f(x_{k+1})-f^\star
\le f(y_k)-f^\star-\frac{\alpha}{2}\|\nabla f(y_k)\|^{2}.
\tag{P5}
\]

\noindent\textbf{Step 6 (Combine the three ingredients).}  
Insert \eqref{P5} into the definition \eqref{P1} of $\Phi_{k+1}$:
\[
\begin{aligned}
\Phi_{k+1}
&= \Delta_{k+1}
   +\frac{1-\beta_{k+1}}{2\alpha}\|x_{k+1}-x_k\|^{2}\\
&\le \Delta_k-\frac{\alpha}{2}\|\nabla f(y_k)\|^{2}
   +\frac{1-\beta_{k+1}}{2\alpha}\|x_{k+1}-x_k\|^{2}.
\end{aligned}
\tag{P6}
\]

\noindent\textbf{Step 7 (Insert the kinetic bound).}  
Using \eqref{P4} in the last term of \eqref{P6} we obtain
\[
\begin{aligned}
\Phi_{k+1}
&\le \Delta_k-\frac{\alpha}{2}\|\nabla f(y_k)\|^{2}
   +\frac{1-\beta_{k+1}}{2\alpha}
     \bigl[2\beta_k^{2}\|x_k-x_{k-1}\|^{2}
           +2\alpha^{2}\|\nabla f(y_k)\|^{2}\bigr] \\[1mm]
&= \Delta_k
   +\frac{1-\beta_{k+1}}{\alpha}\beta_k^{2}\|x_k-x_{k-1}\|^{2}
   -\frac{\alpha}{2}\|\nabla f(y_k)\|^{2}
   +(1-\beta_{k+1})\alpha\|\nabla f(y_k)\|^{2}.
\end{aligned}
\tag{P7}
\]

\noindent\textbf{Step 8 (Correct handling of the gradient terms).}  
The coefficient of $\|\nabla f(y_k)\|^{2}$ in \eqref{P7} equals
\[
-\frac{\alpha}{2}+(1-\beta_{k+1})\alpha
= \alpha\Bigl(\frac12-\beta_{k+1}\Bigr).
\tag{P8}
\]
For early iterations ($k\le 3$) this quantity can be **non‑negative**,
so we cannot claim a monotone decrease of $\Phi_k$ for all $k$.
Instead we treat the first $K:=4$ steps separately and prove a
decrease **from iteration $k\ge K$ onward**, where $\beta_{k+1}\ge\frac12$ and the
coefficient becomes non‑positive.

\noindent\textbf{Step 9 (Algebraic inequality for the kinetic part).}  
For $k\ge K$ we have $\beta_{k+1}\ge\frac12$, and a direct computation shows
\[
\frac{1-\beta_{k+1}}{\alpha}\beta_k^{2}
\le \frac{1-\beta_k}{\alpha},
\qquad\forall k\ge0.
\tag{P9}
\]
\emph{Derivation.}  Substituting the explicit formula $\beta_k=(k-1)/(k+2)$,
\[
\frac{1-\beta_{k+1}}{\alpha}\beta_k^{2}
= \frac{1-\frac{k}{k+3}}{\alpha}\Bigl(\frac{k-1}{k+2}\Bigr)^{2}
= \frac{3}{(k+3)\alpha}\Bigl(\frac{k-1}{k+2}\Bigr)^{2}
\le \frac{1-\frac{k-1}{k+2}}{\alpha}
= \frac{1-\beta_k}{\alpha},
\]
where the inequality follows from the elementary fact that
$\displaystyle\frac{3(k-1)^{2}}{(k+3)(k+2)^{2}}\le\frac{3}{k+3}\le
1-\frac{k-1}{k+2}$ for every $k\ge0$. \qedhere

\noindent\textbf{Step 10 (Monotone decrease for $k\ge K$).}  
Using \eqref{P9} and the fact that $\frac12-\beta_{k+1}\le0$ for $k\ge K$,
\eqref{P7} simplifies to
\[
\Phi_{k+1}\le
\Delta_k+\frac{1-\beta_k}{2\alpha}\|x_k-x_{k-1}\|^{2}
= \Phi_k,
\qquad\forall k\ge K,
\]
and, more precisely,
\[
\Phi_{k+1}\le \Phi_k-\frac{\alpha}{2}\|\nabla f(y_k)\|^{2},
\qquad\forall k\ge K.
\tag{P10}
\]

\noindent\textbf{Step 11 (Bounding the first $K$ iterates).}  
For $k=0,\dots,K-1$ we use Lemma~\ref{lem:grad-bound} together with the
definition of $y_k$ and the bound $\|y_k-x_k\|\le\|x_k-x_{k-1}\|$:
\[
\begin{aligned}
\|\nabla f(y_k)\|^{2}
&\le 2L\bigl(f(y_k)-f^\star\bigr) \\
&\le 2L\Bigl(\Delta_k+\frac{L}{2}\|y_k-x_k\|^{2}\Bigr) \quad\text{(by Lemma~\ref{lem:smooth})}\\
&\le 2L\Bigl(\Delta_k+\frac{L}{2}\|x_k-x_{k-1}\|^{2}\Bigr).
\end{aligned}
\]
Because $\Phi_k\ge\Delta_k$ and $\Phi_k\ge\frac{1-\beta_k}{2\alpha}\|x_k-x_{k-1}\|^{2}$
we have $\|x_k-x_{k-1}\|^{2}\le \frac{2\alpha}{1-\beta_k}\Phi_k\le
\frac{2\alpha}{1-\beta_K}\Phi_0$, where $\Phi_0=\Delta_0$.
Consequently there exists a constant $C_0$ (depending only on
$\Delta_0$, $L$, $\alpha$ and $K$) such that
\[
\sum_{k=0}^{K-1}\|\nabla f(y_k)\|^{2}\le C_0.
\tag{P11}
\]

\noindent\textbf{Step 12 (Summation for the tail).}  
Iterating \eqref{P10} from $k=K$ to $k=T-1$ and using $\Phi_T\ge0$ yields
\[
\frac{\alpha}{2}\sum_{k=K}^{T-1}\|\nabla f(y_k)\|^{2}
\le \Phi_K\le\Phi_0=\Delta_0 .
\tag{P12}
\]

\noindent\textbf{Step 13 (Combine early and tail bounds).}  
Adding \eqref{P11} and \eqref{P12} we obtain for any $T\ge K$,
\[
\sum_{k=0}^{T-1}\|\nabla f(y_k)\|^{2}
\le C_0+\frac{2\Delta_0}{\alpha}
\le \frac{2\bigl(f(x_0)-f^\star\bigr)}{\alpha}+C_0 .
\]
Dividing by $T$ and noting that $C_0/T\le C_0/T$ gives the desired rate
\eqref{T1} (the additive constant $C_0/T$ is dominated by the $1/T$ term for
all $T\ge1$).  Hence the bound in Theorem~\ref{thm:main} holds. \qed

--------------------------------------------------------------------

\section*{Rate Derivation (With Constants)}
From \eqref{T1} we directly read the constants:
\[
C_1:=2\bigl(f(x_0)-f^\star\bigr),\qquad
\bar{G}_T\le \frac{C_1}{\alpha\,T}.
\]
If the stepsize is chosen as the maximal admissible value $\alpha=1/L$,
the bound becomes
\[
\bar{G}_T\le \frac{2L\bigl(f(x_0)-f^\star\bigr)}{T}.
\]

